const THRESHOLD = 480;
const OFFSET = 50;

function processPath(d) {
  const commands = d.match(/[a-zA-Z][^a-zA-Z]*/g);
  let newD = "";

  commands.forEach(cmd => {
    const type = cmd[0];
    const args = cmd.slice(1).trim().split(/[\s,]+/).map(parseFloat);
    
    // We assume all coordinates are absolute for this specific path
    // M x y
    // C x1 y1 x2 y2 x y
    // L x y
    // Z
    
    let newArgs = [];
    
    if (type === 'M' || type === 'L') {
      for (let i = 0; i < args.length; i += 2) {
        let x = args[i];
        let y = args[i+1];
        if (y > THRESHOLD) {
          y -= OFFSET;
        }
        newArgs.push(x, y);
      }
    } else if (type === 'C') {
      for (let i = 0; i < args.length; i += 2) {
        let x = args[i];
        let y = args[i+1];
        if (y > THRESHOLD) {
          y -= OFFSET;
        }
        newArgs.push(x, y);
      }
    } else if (type === 'Z' || type === 'z') {
      // No args
    } else {
      console.log("Unknown command:", type);
      newArgs = args;
    }
    
    newD += type + newArgs.join(" ") + " ";
  });
  
  return newD.trim();
}

